    "id": "training_at_scale__sequence_packing_doc_masking",
    "domain": "training_at_scale",
    "domainLabel": "Training At Scale",
    "algo": "sequence_packing_doc_masking",
    "algoName": "Sequence Packing Doc Masking",
    "title": "Sequence Packing with Block-Diagonal Document Masking",
